import{_ as t,o as a,c as i,a0 as o}from"./chunks/framework.Bmhw_dvp.js";const p=JSON.parse('{"title":"AI Visual Generation","description":"Use the Visual Stage to write prompts, generate static images with Imagen, or create video loops with Veo.","frontmatter":{"title":"AI Visual Generation","description":"Use the Visual Stage to write prompts, generate static images with Imagen, or create video loops with Veo."},"headers":[],"relativePath":"user_guides/visual-generation.md","filePath":"user_guides/visual-generation.md"}'),s={name:"user_guides/visual-generation.md"};function r(n,e,l,c,g,u){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="ai-visual-generation" tabindex="-1">AI Visual Generation <a class="header-anchor" href="#ai-visual-generation" aria-label="Permalink to &quot;AI Visual Generation&quot;">​</a></h1><p>The Visual Stage is your director&#39;s monitor.</p><h2 id="writing-effective-prompts" tabindex="-1">Writing Effective Prompts <a class="header-anchor" href="#writing-effective-prompts" aria-label="Permalink to &quot;Writing Effective Prompts&quot;">​</a></h2><p>When you select a scene, the AI Director suggests a visual prompt based on the script text and character descriptions. You can manually edit this prompt.</p><ul><li>Be descriptive about lighting and camera angles.</li><li>Keep style keywords consistent across scenes.</li></ul><h2 id="image-vs-video" tabindex="-1">Image vs Video <a class="header-anchor" href="#image-vs-video" aria-label="Permalink to &quot;Image vs Video&quot;">​</a></h2><p>Toggle between <strong>Static Image</strong> and <strong>Loop Video</strong> in the Visual Stage:</p><ul><li><strong>Image</strong>: Uses Google&#39;s Imagen model for rapid, high-quality static frames.</li><li><strong>Video</strong>: Uses Google&#39;s Veo 3.1 model to generate dynamic looping clips based on your prompt.</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>You can also upload your own custom media using the <strong>Upload Custom</strong> button.</p></div>',9)])])}const m=t(s,[["render",r]]);export{p as __pageData,m as default};
